"/us/en/endoscopy/products/1588-aim-camera-system": {"template":"product-detail","metadata":{"title":"1588 AIM camera system","pageTitle":null,"description":"High-definition camera system designed to help distinguish critical anatomy with 9 dedicated surgical camera specialty settings and 5 advanced imaging modalities: ENV, IRIS, Clarity, DRE, and DESAT.\r\n","image":"/content/dam/stryker/endoscopy/products/1588aimcamerasystem/images/1588Thumb.jpg","imageAlt":"1588 AIM camera system","tags":["stryker:capability/surgical-visualization","stryker:content-type/product","stryker:portfolio/medical-and-surgical-equipment","stryker:business-unit/endoscopy","stryker:specialty/camera-systems","stryker:services/procare/endoscopy/surgical-visualization/camera-systems","stryker:content-type/hcp_content","stryker:product/endoscopy/1588-aim-camera-system"],"originallyPublished":"2023-02-06T22:23:14.000Z","lastPublished":"2026-06-30T18:23:48.000Z","contentID":"Literature Number: 1000902487, Rev. A"},"anchors":[],"disclaimer":null,"forms":[{"formId":"4047","afterSubmitAction":"showMessage","message":"Thank you! We have received your request. A Stryker representative will be in contact with you soon.","useProduction":true}],"tabs":[],"cardLists":[{"component":"customizable_copy_co","title":"Related Products","items":[{"path":"/us/en/endoscopy/systems/1688-aim-platform","resolved":true,"title":"1688 Advanced Imaging Modalities (AIM) 4K Platform","description":"laparoscopic tower, endoscopic tower, stryker 1688","image":"/content/dam/stryker/endoscopy/systems/1688/main-page/images/1688-AssetsThumbnail.jpg","alt":null}]}],"missingAlt":[]},
