"/us/en/foot-and-ankle/products/salvation-plating": {"template":"product-detail","metadata":{"title":"Salvation 3Di Plating System","pageTitle":"Salvation 3Di Plating System","description":"Salvation 3Di Plating System is designed to address the unique demands of advanced midfoot reconstruction. The system focuses on treating cases such as neuropathic deformity requiring arthrodesis of the medial column, with or without corrective osteotomies. Stryker - Wright Medical Group","image":"/content/dam/stryker/foot-and-ankle/products/all-products/2024-brandrefresh/product-thumbnails/Thumb-Salvation2Plating.png","imageAlt":"Salvation 3Di Plating System - Wright Medical Stryker","tags":["stryker:custom/foot-and-ankle/product-type/Plating-platform","stryker:content-type/product","stryker:business-unit/foot-and-ankle","stryker:capability/foot-and-ankle","stryker:portfolio/orthopaedics","stryker:content-type/hcp_content","stryker:audience/medical_professionals","stryker:procedure/foot-and-ankle/charcot-neuroarthropathy/plating-platforms"],"originallyPublished":"2024-10-15T14:09:54.000Z","lastPublished":"2025-10-23T20:06:15.000Z","contentID":"AP-017735"},"anchors":[{"id":"specification","title":"specification","hidden":true,"type":"section-title","area":"customizablearea_parsys"},{"id":"contact","title":"Connect with us","hidden":false,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":null,"forms":[{"formId":"3079","afterSubmitAction":"showMessage","message":"Thank you!","useProduction":true},{"formId":"1079","afterSubmitAction":"showMessage","message":"Thank you!","useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/foot-and-ankle/products/smart-toe-ii": {"template":"product-detail","metadata":{"title":"Smart Toe II","pageTitle":null,"description":"Our premier hammertoe treatment, Smart Toe II is a one piece, dynamic compression implant for hammertoe correction.","image":"/content/dam/stryker/foot-and-ankle/products/smarttoeii/images/page_thumbnail_smarttoe.jpg","imageAlt":"Smart Toe","tags":["stryker:content-type/product","stryker:product/foot-and-ankle/smart-toe-ii","stryker:custom/foot-and-ankle/product-type/hammertoe-solutions","stryker:business-unit/foot-and-ankle","stryker:procedure/foot-and-ankle/hammertoe-correction-(pip-dip-joint)/hammertoe-solutions","stryker:capability/foot-and-ankle","stryker:portfolio/orthopaedics","stryker:content-type/hcp_content"],"originallyPublished":"2023-02-06T18:49:48.000Z","lastPublished":"2026-05-19T18:49:48.000Z","contentID":"FA-SMTO-SYK-3265152_REV-0_en_us"},"anchors":[],"disclaimer":null,"forms":[{"formId":"3079","afterSubmitAction":"showMessage","message":"Thank you!","useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":["/content/dam/stryker/foot-and-ankle/images/header_forefoot.jpg"]},
