"/us/en/neurovascular/products/transend--guidewires": {"template":"product-detail","metadata":{"title":"Transend","pageTitle":"Transend Guidewires","description":"Transend Guidewires offer control and responsiveness. Their lubricious coating facilitates their advancement through a microcatheter or tortuous neurovasculature. ","image":"/content/dam/stryker/neurovascular/products/transend-guidewires/images/Thumbnail_Transcend Guidewires.jpg","imageAlt":"Transend","tags":["stryker:content-type/product","stryker:specialty/access","stryker:specialty/acute-ischemic-stroke-ais","stryker:portfolio/neurotechnology","stryker:product/neurovascular/transend-guidewires","stryker:business-unit/neurovascular","stryker:capability/neurovascular","stryker:content-type/hcp_content","stryker:specialty/hemorrhagic-stroke-hem"],"originallyPublished":"2023-02-06T16:51:12.000Z","lastPublished":"2025-01-08T16:51:12.000Z","contentID":"AP001666 v2.0"},"anchors":[{"id":"features","title":"Features and benefits","hidden":false,"type":"section-title","area":"customizablearea_parsys"},{"id":"specifications","title":"Product specifications","hidden":false,"type":"section-title","area":"customizablearea_parsys"},{"id":"specifications","title":"Safety Information","hidden":false,"type":"section-title","area":"customizablearea_parsys"}],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
